// Node.js 22+. Run from the repository root with a downloaded official schema.
// This inventories assertions; it does not validate a descriptor.
import fs from 'node:fs';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';

const input = process.argv[2];
assert(input, 'Supply odcs-json-schema-v3.2.0.json as the first argument.');
const bytes = fs.readFileSync(input);
const schema = JSON.parse(bytes);
assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'),
  'edb41f33ec46e84780e99872ab2bd67f074959d2bf3e9c9fc54e61f8982b0d93',
  'Official artifact bytes changed; review the version and coverage before updating the fingerprint.');
assert.equal(schema.$schema, 'https://json-schema.org/draft/2019-09/schema');
assert.equal(schema.properties.apiVersion.default, 'v3.2.0');
const annotations = new Set(['$schema', '$id', '$anchor', '$comment', 'title', 'description',
  'default', 'examples', 'deprecated', 'readOnly', 'writeOnly']);
const maps = new Set(['properties', 'patternProperties', '$defs', 'dependentSchemas']);
const singles = new Set(['items', 'additionalItems', 'contains', 'propertyNames',
  'additionalProperties', 'unevaluatedProperties', 'unevaluatedItems', 'not', 'if', 'then', 'else']);
const lists = new Set(['allOf', 'anyOf', 'oneOf', 'prefixItems']);
const assertions = new Set(['$ref', '$recursiveRef', '$recursiveAnchor', 'type', 'enum', 'const',
  'required', 'dependentRequired', 'minLength', 'maxLength', 'pattern', 'format',
  'minimum', 'maximum', 'exclusiveMinimum', 'exclusiveMaximum', 'multipleOf',
  'minItems', 'maxItems', 'uniqueItems', 'minContains', 'maxContains', 'minProperties', 'maxProperties']);
const escapePointer = value => value.replaceAll('~', '~0').replaceAll('/', '~1');
const code = value => '<code>' + JSON.stringify(value).replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('|', '&#124;') + '</code>';
const groups = new Map();
let count = 0;
function visit(node, pointer, group) {
  // Upstream uses ServerSource as a reference-addressed container, not a schema.
  if (pointer === '#/$defs/ServerSource') {
    for (const [name, child] of Object.entries(node)) visit(child, pointer + '/' + name, name);
    return;
  }
  if (typeof node === 'boolean') {
    add(pointer, code(node), group);
    return;
  }
  assert(node && typeof node === 'object' && !Array.isArray(node), pointer);
  for (const [key, value] of Object.entries(node)) {
    if (annotations.has(key)) continue;
    const location = pointer + '/' + escapePointer(key);
    if (maps.has(key)) {
      for (const [name, child] of Object.entries(value))
        visit(child, location + '/' + escapePointer(name), key === '$defs' ? name : group);
    } else if (singles.has(key)) {
      add(location, 'Apply subschema below', group);
      visit(value, location, group);
    } else if (lists.has(key)) {
      add(location, `${value.length} branches (${key})`, group);
      value.forEach((child, index) => visit(child, location + '/' + index, group));
    } else {
      assert(assertions.has(key), `Unclassified schema keyword ${location}; update generator.`);
      add(location, code(value), group);
    }
  }
}
function add(pointer, value, group) {
  if (!groups.has(group)) groups.set(group, []);
  groups.get(group).push(`| \`${pointer}\` | ${value} | Unsupported as JSON Schema enforcement; see matrix |`);
  count++;
}
visit(schema, '#', 'Contract');
const output = `---
title: ODCS schema assertion inventory
parent: Contracts and standards
nav_exclude: true
permalink: /standards/odcs-schema-assertions/
---

<!-- Generated by .github/scripts/Generate-OdcsValidationInventory.mjs. -->

This is the exhaustive keyword-path companion to the
[ODCS validation matrix]({{ '/standards/odcs-validation/' | relative_url }}).
Version: **ODCS 3.2.0**, JSON Schema **2019-09**.
[Official source](https://github.com/bitol-io/open-data-contract-standard/blob/v3.2.0/schema/odcs-json-schema-v3.2.0.json).
Source SHA-256: \`${crypto.createHash('sha256').update(bytes).digest('hex')}\`.

Each of the **${count} entries** identifies an assertion, reference or applicator at
its exact JSON Pointer. Origin for every row is the official ODCS companion schema;
layer is JSON Schema (format assertions depend on validator configuration).
Packata does not execute this artifact. The status column describes that missing
enforcement layer, not the absence of equivalent individual semantic checks.
The matrix records those implemented/partial checks, code/tests and gap tracking.

References apply at every use site, including recursive nested properties, items
and map members. A branch's assertions apply only when selected by its parent
applicator: allOf requires all, anyOf at least one, oneOf exactly one; if selects
then/else. A false schema prohibits that location. Required means presence, not
non-empty text. Properties does not itself require a member. Omitted closure
keywords permit additional members. Defaults, examples, descriptions and deprecation
are annotations and are intentionally excluded; they do not reject input or fill defaults.

Regenerate with Node.js 22+ from the repository root:

\`\`\`console
node .github/scripts/Generate-OdcsValidationInventory.mjs path/to/odcs-json-schema-v3.2.0.json
node .github/scripts/Generate-OdcsValidationInventory.mjs path/to/odcs-json-schema-v3.2.0.json --check
\`\`\`

${[...groups].map(([name, rows]) => `## ${name}\n\n| Schema keyword path | Constraint / applicator | Current Packata status |\n| --- | --- | --- |\n${rows.join('\n')}`).join('\n\n')}
`;
const target = 'docs/odcs-schema-assertions.md';
if (process.argv.includes('--check')) assert.equal(fs.readFileSync(target, 'utf8').replaceAll('\r\n', '\n'), output, 'Inventory is stale.');
else fs.writeFileSync(target, output);
console.log(`${count} schema entries ${process.argv.includes('--check') ? 'verified' : 'generated'}.`);
